-- Create "transactional_emails" table
CREATE TABLE "public"."transactional_emails" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "channel" character varying NOT NULL DEFAULT 'email',
  "destination" character varying NOT NULL,
  "template_id" bigint NOT NULL,
  "contact_id" bigint NULL,
  "status" character varying NOT NULL DEFAULT 'pending',
  "error" character varying NULL,
  "idempotency_key" character varying NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "workspace_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "transactional_emails_workspaces_transactional_emails" FOREIGN KEY ("workspace_id") REFERENCES "public"."workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create index "transactional_emails_workspace_id_idempotency_key" to table: "transactional_emails"
CREATE UNIQUE INDEX "transactional_emails_workspace_id_idempotency_key" ON "public"."transactional_emails" ("workspace_id", "idempotency_key");
-- Create index "transactionalemail_workspace_id_created_at" to table: "transactional_emails"
CREATE INDEX "transactionalemail_workspace_id_created_at" ON "public"."transactional_emails" ("workspace_id", "created_at");
